package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A sheet, keyed by the id a user types; created the first time it is loaded. Its settings that carry a
 * figure are dated, each kept as a {@link SheetSetting}; see {@link DatedSettings}.
 */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The floor a sheet starts with. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms a sheet starts with, in days. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent a sheet starts with. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    /** The sheet's today: the date every date-dependent decision on the sheet uses. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The number given to the last claim opened on the sheet; 0 before any is opened. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** The date a claim's rounding turns on: half up before it, half to even on or after it; null: the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** From the sheet's today on this date, a claim opened is numbered within its period; null: off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    /** While set, the date a new claim takes when none is given, in place of the sheet's today; null: off. */
    @Column(name = "entry_date")
    private LocalDate entryDate;

    /** An open period whose to-date plus these days is before a new today is closed when the today is changed; null: off. */
    @Column(name = "grace_days")
    private Integer graceDays;

    /** Whether a steward has archived the sheet: it stays visible and every change to it is refused. */
    @Column(name = "archived", nullable = false)
    private boolean archived;

    protected Sheet() {
    }

    public Sheet(String id, String createdBy, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.today = today;
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    public LocalDate getEntryDate() {
        return entryDate;
    }

    public void setEntryDate(LocalDate entryDate) {
        this.entryDate = entryDate;
    }

    public Integer getGraceDays() {
        return graceDays;
    }

    public void setGraceDays(Integer graceDays) {
        this.graceDays = graceDays;
    }

    public boolean isArchived() {
        return archived;
    }

    public void setArchived(boolean archived) {
        this.archived = archived;
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import net.officefloor.hq.app.access.AccessService;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Sheet endpoints. The signed-in user's name comes in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets")
@Validated
public class SheetController {

    public record SheetView(String id, LocalDate today, boolean archived) {

        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.isArchived());
        }
    }

    public record TodayChange(@NotNull LocalDate today) {
    }

    private final SheetService service;
    private final AccessService access;

    public SheetController(SheetService service, AccessService access) {
        this.service = service;
        this.access = access;
    }

    @PostMapping("/{id}/load")
    public SheetView load(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank String user) {
        return SheetView.of(service.load(id.trim(), user.trim()));
    }

    /** The sheet as shown: under an as-of view, its today is the as-of date and the rest as it stood then. */
    @GetMapping("/{id}")
    public SheetView get(@PathVariable @NotBlank @Size(max = 100) String id) {
        return SheetView.of(service.get(id.trim()));
    }

    @PutMapping("/{id}/today")
    public SheetView setToday(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody TodayChange change) {
        return SheetView.of(service.setToday(id.trim(), user.trim(), change.today()));
    }

    /** Archive the sheet: a steward only, and once; anyone else, or again, is refused (403). */
    @PostMapping("/{id}/archive")
    public SheetView archive(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank String user) {
        return SheetView.of(access.archive(id.trim(), user.trim()));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/**
 * A claim a person makes: an amount (two decimals), a date, a note and a status. A negative amount is a
 * correction, naming the number of the SETTLED claim of the same person it corrects.
 */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The number the claim got when opened; null while a draft; a voided claim keeps it. */
    @Column(name = "claim_number")
    private Integer number;

    /** The sequence a period-numbered claim counts in ('P<period id>', or 'X' for no period); null otherwise. */
    @Column(name = "period_sequence")
    private String periodSequence;

    /** The claim's place in its period sequence; null for a sheet-wide number. */
    @Column(name = "period_seq_number")
    private Integer periodSeqNumber;

    /** The number as shown for a period-numbered claim (<period name>-<n>, or X-<n>); null otherwise. */
    @Column(name = "period_number")
    private String periodNumber;

    /** The user who opened the claim; null while a draft and once voided. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The user who last edited the claim; null while never edited. */
    @Column(name = "edited_by")
    private String editedBy;

    /** The due fixed when the claim was settled; null while not settled or when there was no rate. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** Whether the person's last statement bound the claim to statedDue. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the last statement bound the claim to; null while unbound or when it had none. */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** The number of the claim a correction corrects; null for any other claim. */
    @Column(name = "corrects")
    private String corrects;

    /** The date of the claim a correction corrects, which its rounding goes by; null for any other claim. */
    @Column(name = "corrects_date")
    private LocalDate correctsDate;

    /**
     * The date the claim is due by, fixed when it was added: the terms-th business day after its date, by the
     * terms then of its person's grade on its date and the holidays on the sheet then. A holiday added later
     * fixes it again over the holidays then, with the same terms (see {@link #terms}).
     */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The terms (in business days) the claim's due-by was fixed with. */
    @Column(name = "terms", nullable = false)
    private int terms;

    /** The date the claim is deferred until; null when it was never deferred. See {@link Dues#deferred}. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** The last sheet's today a reminder was written for the claim; null when it was never reminded. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** How many proofs the claim has; it starts at 0. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** The number (as shown) of the claim this one was split off; null for any claim not split off another. */

